namespace sv_cdec865f5898455cacefcc94f3d2854a.Services;

/// <summary>
/// Scoped service (one per Blazor circuit) that holds the currently selected
/// warehouse and notifies all subscribers when it changes.
/// </summary>
public sealed class WarehouseStateService
{
    public static readonly IReadOnlyList<(string Id, string Name)> AvailableWarehouses =
    [
        ("WH-A", "Warehouse A"),
        ("WH-B", "Warehouse B"),
        ("WH-C", "Warehouse C"),
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.First(w => w.Id == _currentWarehouseId).Name;

    /// <summary>Raised on the caller's thread — subscribers must call InvokeAsync/StateHasChanged.</summary>
    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;

        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_cdec865f5898455cacefcc94f3d2854a.Services;

/// <summary>
/// Scoped service that simulates checking for low-stock items.
/// Holds the latest count and notifies all subscribed components when it changes.
/// </summary>
public sealed class InventoryAlertService
{
    private static readonly Random s_random = new();

    public int LatestLowStockCount { get; private set; }

    /// <summary>Raised whenever fresh alert data is available.</summary>
    public event Action? OnAlertCountChanged;

    /// <summary>Simulates a database query — returns a random number between 0 and 15.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate async DB call
        int count = s_random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Called by the polling component to push a fresh count.
    /// Stores the value and notifies every subscriber.
    /// </summary>
    public void PublishCount(int count)
    {
        LatestLowStockCount = count;
        OnAlertCountChanged?.Invoke();
    }
}

