@using sv_cdec865f5898455cacefcc94f3d2854a.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard — @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Dashboard</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Selected Warehouse</h5>
                <p class="card-text fs-4">@WarehouseState.CurrentWarehouseName</p>
            </div>
        </div>
    </div>
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="card-text fs-4">
                    @if (_isPolling)
                    {
                        <span class="@(AlertService.LatestLowStockCount > 0 ? "text-danger" : "text-success")">
                            @AlertService.LatestLowStockCount item(s) below minimum
                        </span>
                        <br />
                        <small class="text-muted">Polling every 10 seconds</small>
                    }
                    else
                    {
                        <span class="text-muted">Starting…</span>
                    }
                </p>
            </div>
        </div>
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;
    private bool _isPolling;

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleWarehouseChanged;
        AlertService.OnAlertCountChanged += HandleAlertChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await StartPollingAsync();
        }
    }

    private async Task StartPollingAsync()
    {
        StopPolling();

        _cts = new CancellationTokenSource();
        var token = _cts.Token;

        // Fetch immediately, then every 10 seconds
        await PollOnceAsync();
        _isPolling = true;
        StateHasChanged();

        _ = Task.Run(async () =>
        {
            using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            try
            {
                while (await timer.WaitForNextTickAsync(token))
                {
                    await PollOnceAsync();
                }
            }
            catch (OperationCanceledException) { }
        }, token);
    }

    private async Task PollOnceAsync()
    {
        var count = await AlertService.GetLowStockCountAsync(WarehouseState.CurrentWarehouseId);
        // Publish to ALL subscribers via the shared service
        AlertService.PublishCount(count);
    }

    private void HandleWarehouseChanged()
    {
        // Warehouse changed — restart polling for the new warehouse
        InvokeAsync(async () =>
        {
            await StartPollingAsync();
        });
    }

    private void HandleAlertChanged() => InvokeAsync(StateHasChanged);

    private void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _isPolling = false;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleWarehouseChanged;
        AlertService.OnAlertCountChanged -= HandleAlertChanged;
        StopPolling();
    }
}

